from z3 import *

def solve_graph():
    V = 19
    E = [[Bool(f"e_{i}_{j}") if i < j else False for j in range(V)] for i in range(V)]

    s = Solver()

    # Number of edges >= 29
    edge_vars = [E[i][j] for i in range(V) for j in range(i+1, V)]
    s.add(Sum([If(e, 1, 0) for e in edge_vars]) >= 29)

    # 3-colorable
    colors = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(colors[i] >= 0, colors[i] <= 2)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(E[i][j], colors[i] != colors[j]))

    # Girth >= 7 (no cycles of length 3, 4, 5, 6)
    # To do this efficiently, we can just enumerate all possible cycles of length 3, 4, 5, 6
    # and say not all edges in the cycle are true.
    import itertools

    # length 3
    for c in itertools.combinations(range(V), 3):
        s.add(Not(And(E[c[0]][c[1]], E[c[0]][c[2]], E[c[1]][c[2]])))

    # length 4
    for c in itertools.combinations(range(V), 4):
        for p in itertools.permutations(c):
            if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
                s.add(Not(And(
                    E[min(p[0], p[1])][max(p[0], p[1])],
                    E[min(p[1], p[2])][max(p[1], p[2])],
                    E[min(p[2], p[3])][max(p[2], p[3])],
                    E[min(p[3], p[0])][max(p[3], p[0])]
                )))

    # length 5
    for c in itertools.combinations(range(V), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                s.add(Not(And(
                    E[min(p[0], p[1])][max(p[0], p[1])],
                    E[min(p[1], p[2])][max(p[1], p[2])],
                    E[min(p[2], p[3])][max(p[2], p[3])],
                    E[min(p[3], p[4])][max(p[3], p[4])],
                    E[min(p[4], p[0])][max(p[4], p[0])]
                )))

    # length 6
    for c in itertools.combinations(range(V), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                s.add(Not(And(
                    E[min(p[0], p[1])][max(p[0], p[1])],
                    E[min(p[1], p[2])][max(p[1], p[2])],
                    E[min(p[2], p[3])][max(p[2], p[3])],
                    E[min(p[3], p[4])][max(p[3], p[4])],
                    E[min(p[4], p[5])][max(p[4], p[5])],
                    E[min(p[5], p[0])][max(p[5], p[0])]
                )))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve_graph()

from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

V = 19

def edge_var(u, v):
    if u > v:
        u, v = v, u
    idx = u * V - u * (u + 1) // 2 + v - u
    return idx

num_edges = V * (V - 1) // 2

def solve_for_E(E):
    solver = Glucose4()
    edge_vars = list(range(1, num_edges + 1))
    cnf = CardEnc.atleast(lits=edge_vars, bound=E, encoding=1)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    def add_no_cycle(length):
        for c in itertools.combinations(range(V), length):
            for p in itertools.permutations(c):
                if p[0] == min(p) and p[1] < p[-1]:
                    clause = [-edge_var(p[i], p[(i+1)%length]) for i in range(length)]
                    solver.add_clause(clause)

    add_no_cycle(3)
    add_no_cycle(4)
    add_no_cycle(5)
    add_no_cycle(6)

    return solver.solve()

print("E=29:", solve_for_E(29))

