from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

def max_edges_girth_7(V):
    def solve_for_E(E):
        solver = Glucose4()
        num_edges = V * (V - 1) // 2

        def edge_var(u, v):
            if u > v: u, v = v, u
            return u * V - u * (u + 1) // 2 + v - u

        edge_vars = list(range(1, num_edges + 1))
        cnf = CardEnc.atleast(lits=edge_vars, bound=E, encoding=1)
        for clause in cnf.clauses:
            solver.add_clause(clause)

        def add_no_cycle(length):
            for c in itertools.combinations(range(V), length):
                for p in itertools.permutations(c):
                    if p[0] == min(p) and p[1] < p[-1]:
                        clause = [-edge_var(p[i], p[(i+1)%length]) for i in range(length)]
                        solver.add_clause(clause)

        add_no_cycle(3)
        add_no_cycle(4)
        add_no_cycle(5)
        add_no_cycle(6)

        return solver.solve()

    low = 0
    high = V * 2
    best = 0
    while low <= high:
        mid = (low + high) // 2
        if solve_for_E(mid):
            best = mid
            low = mid + 1
        else:
            high = mid - 1
    return best

print("Max edges for V=10:", max_edges_girth_7(10))
print("Max edges for V=14:", max_edges_girth_7(14))
